package it.comune.trieste.ouf.ingestion;
import java.time.Duration;import java.util.*;import org.springframework.jdbc.core.simple.JdbcClient;import org.springframework.stereotype.Repository;import org.springframework.transaction.annotation.Transactional;
@Repository public class OnboardingReviewRepository {private final JdbcClient sql;public OnboardingReviewRepository(JdbcClient sql){this.sql=sql;}@Transactional public Optional<Claim> claim(String worker,Duration lease){return sql.sql("with candidate as (select request_id from ouf_ingestion.onboarding_review_outbox where state in('READY','FAILED_RETRYABLE') and next_attempt_at<=transaction_timestamp() and (lease_until is null or lease_until<transaction_timestamp()) order by next_attempt_at,created_at for update skip locked limit 1) update ouf_ingestion.onboarding_review_outbox o set state='DELIVERING',attempts=attempts+1,lease_owner=:w,lease_until=transaction_timestamp()+(:m*interval '1 millisecond') from candidate c,ouf_ingestion.runtime_issue i where o.request_id=c.request_id and i.issue_id=o.issue_id returning o.request_id,o.issue_id,i.source_id,i.evidence_ref,o.correlation_id,o.idempotency_key").param("w",worker).param("m",lease.toMillis()).query((r,n)->new Claim(r.getObject(1,UUID.class),r.getObject(2,UUID.class),r.getString(3),r.getString(4),r.getString(5),r.getString(6),worker)).optional();}@Transactional public void acknowledge(Claim c,String reviewRef){int n=sql.sql("update ouf_ingestion.onboarding_review_outbox set state='ACKED',onboarding_review_ref=:x,lease_owner=null,lease_until=null where request_id=:r and state='DELIVERING' and lease_owner=:w").param("x",reviewRef).param("r",c.requestId()).param("w",c.worker()).update();if(n!=1)throw new IllegalStateException("ING_ONBOARDING_REVIEW_LEASE_LOST");sql.sql("update ouf_ingestion.runtime_issue set onboarding_review_ref=:x,lock_version=lock_version+1 where issue_id=:i and status='OPEN'").param("x",reviewRef).param("i",c.issueId()).update();}@Transactional public void fail(Claim c,String code,boolean terminal){sql.sql("update ouf_ingestion.onboarding_review_outbox set state=:s,last_error_code=:c,next_attempt_at=transaction_timestamp()+interval '60 seconds',lease_owner=null,lease_until=null where request_id=:r and state='DELIVERING' and lease_owner=:w").param("s",terminal?"FAILED_TERMINAL":"FAILED_RETRYABLE").param("c",safe(code)).param("r",c.requestId()).param("w",c.worker()).update();}private static String safe(String c){return c!=null&&c.matches("ING_[A-Z0-9_]{1,76}")?c:"ING_ONBOARDING_REVIEW_FAILED";}public record Claim(UUID requestId,UUID issueId,String sourceId,String evidenceRef,String correlationId,String idempotencyKey,String worker){} }
